# area: callables
# hypothesis: A ParamSpec decorator keeps the keyword-only signature so a callback protocol accepts it, while assigning a positional-only function to the same protocol should be rejected and raises TypeError at runtime.
from collections.abc import Callable
from typing import Protocol, reveal_type


class KwCallback(Protocol):
    def __call__(self, *, value: int, scale: int = 1) -> int: ...


def passthrough[**P, R](f: Callable[P, R]) -> Callable[P, R]:
    def inner(*args: P.args, **kwargs: P.kwargs) -> R:
        return f(*args, **kwargs)

    return inner


def positional_only(value: int, scale: int = 1, /) -> int:
    return value * scale


@passthrough
def keyword_only(*, value: int, scale: int = 1) -> int:
    return value * scale


cb: KwCallback = keyword_only
lam: KwCallback = lambda *, value, scale=1: value * scale
reveal_type(cb(value=3))
assert cb(value=3) == 3
assert cb(value=3, scale=2) == 6
assert lam(value=4, scale=2) == 8
assert positional_only(2, 5) == 10


def probe() -> bool:
    bad: KwCallback = positional_only  # expect-error
    try:
        bad(value=3)
    except TypeError:
        return True
    return False


assert probe()
